-- Sprites for the pixel avatars drawn over bots (nametags.lua): one per layer of
-- graphics/avatar-parts.png, as listed in avatar_parts.lua (generated by
-- tools/stream/avatar_sprites.js). Only a world started with this mod has them;
-- without them the runtime draws the name tag alone.
local parts = require('avatar_parts')
local sprites = {}
for i = 1, parts.count do
  sprites[#sprites+1] = {type='sprite', name=parts.prefix .. i, filename=parts.sheet,
    x=((i - 1) % parts.columns) * parts.cell, y=math.floor((i - 1) / parts.columns) * parts.cell,
    width=parts.cell, height=parts.cell, scale=parts.scale, flags={'no-crop'}}
end
data:extend(sprites)
